def item(sec,key,title,text,page,loc,records=(),scope='source_cohort',kind='reported_source_fact',notes=()):
 assert key not in items,key
 e=ev(page,loc);d={'id':key,'title':title,'text':text,'claim_type':kind,'sample_scope':{'formulations':[],'physical_batch_id':None,'scope_kind':scope,'state':title,'link_limit':SCOPE[scope]},'evidence':[e],'source_locators':[e['locator']],'canonical_links':[{'record_id':P+k,'json_pointer':'','relation':SCOPE[scope]} for k in records],'notes':list(notes),'facts':[],'training_eligible':False};items[key]=d;next(s for s in sections if s['id']==sec)['items'].append(d);return d
def more(key,page,loc):
 e=ev(page,loc);items[key]['evidence'].append(e);items[key]['source_locators'].append(e['locator'])
def rows(sec,data):
 for x in data:item(sec,*x)
