(O/'yi2002.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
(O/'reader-items-summary.json').write_text(json.dumps([{'id':i['id'],'title':i['title'],'section':s['id'],'source_locators':i['source_locators']} for s in sections for i in s['items']],ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(json.dumps(out['counts']))
